-- Harold Hughes (profileID=8) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Harold Hughes phrasings

SELECT p.argumentID, p.phrasingID, 8, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 8
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 8 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=8 AND targArgID IN (80,89,90,103,104,105,107,109,110,111,112,113,115,116,118,145,148,153,154,155,166,169,171,174,175,187,200,207,217,218,219,221,222,223,236,240,241,266,349,350,484,500,501,539,546,560,561,574,575,598,603,607,986,1188,1202,1313,1314,1319,1321,1498);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 8
SET pe.active = o.acceptance
WHERE pe.profileID = 8;

SELECT 'Done: endorsements for profileID=8' AS status;